#include <stdio.h>

int main(void) {
    FILE *fp = fopen("dangan.txt", "w");
    if (fp == NULL) {
        printf("档案室的门打不开喵\n");
        return 0;
    }
    fprintf(fp, "小鱼干 3 条\n");
    fprintf(fp, "猫粮 1 碗\n");
    fclose(fp);

    fp = fopen("dangan.txt", "r");
    if (fp == NULL) {
        printf("找不到这本册子喵\n");
        return 0;
    }
    char line[64];
    while (fgets(line, sizeof(line), fp) != NULL) {
        printf("读到：%s", line);
    }
    fclose(fp);
    return 0;
}

#include <stdio.h>

int main(void) {
    FILE *fp = fopen("dangan.txt", "w");
    fprintf(fp, "第一行\n第二行\n");
    fclose(fp);

    fp = fopen("dangan.txt", "r");
    char line[64];
    int n = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        n = n + 1;
        printf("第 %d 行：%s", n, line);
    }
    fclose(fp);
    printf("一共 %d 行\n", n);
    return 0;
}
